	if err != nil {
		t.Fatalf("effective at exact change time: %v", err)
	}
	if got2["checkout"].Version != r2.Version {
		t.Errorf("at changed_at version = %s, want %s (inclusive bound)", got2["checkout"].Version, r2.Version)
	}
}

